from typing import Dict, Any, List
from jinja2 import Template

class ReportGenerator:
    MARKDOWN_TEMPLATE = """# LLM Evaluation & Comparison Report
**Generated by NVIDIA NeMo Evaluator Benchmarking Platform**
*Vishwakarma Institute of Technology, Pune & Tata Consultancy Services (TCS)*

**Run mode: A = {{ comparison.run_mode_a|upper }}, B = {{ comparison.run_mode_b|upper }}**

**Job: A = {{ comparison.job_name_a }}, B = {{ comparison.job_name_b }}**

**Served model: A = `{{ comparison.served_model_id_a }}`, B = `{{ comparison.served_model_id_b }}`**

{% if comparison.model_substituted_a %}
> SUBSTITUTE ROUTE (Run A): requested `{{ comparison.model_a_id }}`, served `{{ comparison.served_model_id_a }}`. {{ comparison.route_note_a }}{% endif %}
{% if comparison.model_substituted_b %}
> SUBSTITUTE ROUTE (Run B): requested `{{ comparison.model_b_id }}`, served `{{ comparison.served_model_id_b }}`. {{ comparison.route_note_b }}{% endif %}

**Reliability: A = {{ "UNRELIABLE" if comparison.unreliable_a else "ok" }} ({{ "%.0f"|format((comparison.unreliable_fraction_a or 0) * 100) }}% of items api_error/truncated/no_answer_found), B = {{ "UNRELIABLE" if comparison.unreliable_b else "ok" }} ({{ "%.0f"|format((comparison.unreliable_fraction_b or 0) * 100) }}%)**
**Scorer version: A = {{ comparison.scorer_version_a }}{{ " (RESCORED)" if comparison.rescored_a else "" }}, B = {{ comparison.scorer_version_b }}{{ " (RESCORED)" if comparison.rescored_b else "" }}**
{% if comparison.failed_a or comparison.failed_b %}
> FAILED RUN: at least one run was stopped early because its model was unavailable. It has only a few items and must not be compared.
{% endif %}
{% if comparison.incomplete_a or comparison.incomplete_b %}
> INCOMPLETE RUN: at least one run never finished, so some benchmarks are missing. It must not be compared.
{% endif %}
{% if comparison.unreliable_benchmarks_a or comparison.unreliable_benchmarks_b %}
> UNRELIABLE BENCHMARK(S): A: {{ comparison.unreliable_benchmarks_a|join(", ") or "none" }}; B: {{ comparison.unreliable_benchmarks_b|join(", ") or "none" }}. More than 20% of the items of those benchmarks were api_error, truncated or no_answer_found, so those rows do not measure the model fairly, even if the run as a whole is under 10%.
{% endif %}
{% if comparison.rescored_a or comparison.rescored_b %}
> RESCORED: at least one run was re-scored offline from its stored replies with the scorer version shown above (original run: A = {{ comparison.rescored_from_a or "n/a" }}, B = {{ comparison.rescored_from_b or "n/a" }}). No model was called again.
{% endif %}
{% if comparison.scorer_version_a != comparison.scorer_version_b %}
> WARNING: the two runs were scored with different scorer versions, so their scores are not directly comparable.
{% endif %}
{% if comparison.unreliable_a or comparison.unreliable_b %}
> UNRELIABLE RUN: more than 10% of the items in at least one run were api_error, truncated or no_answer_found, so its accuracy is not a fair measure of the model. Find the cause (rate limits, a too-small max_tokens, a model that is not available) and rerun before drawing any conclusion.
{% endif %}
{% if comparison.standin_a or comparison.standin_b %}
> STAND-IN RUN: at least one run used a stand-in model (its job name starts with `standin_`). This validates the pipeline only. It is NOT a result for the real models and must not be presented as one.
{% endif %}
{% if comparison.run_mode_a != comparison.run_mode_b %}
> WARNING: these runs have different modes. A comparison between a simulated and a live run is not meaningful.
{% endif %}
{% if "simulated" in (comparison.run_mode_a, comparison.run_mode_b) %}
> SIMULATED RESULTS: at least one run was produced by the built-in mock simulator, not by a real model. The scores demonstrate the pipeline only and say nothing about real model capability.
{% endif %}
{% if "unknown" in (comparison.run_mode_a, comparison.run_mode_b) %}
> NOTE: at least one run is a legacy artifact whose mode was not recorded and cannot be verified.
{% endif %}

---

## 1. Executive Summary

- **Run A**: {{ comparison.model_a_name }} (`{{ comparison.model_a_id }}`) - {{ comparison.run_mode_a }} - served as `{{ comparison.served_model_id_a }}`
- **Run B**: {{ comparison.model_b_name }} (`{{ comparison.model_b_id }}`) - {{ comparison.run_mode_b }} - served as `{{ comparison.served_model_id_b }}`
- **Total Aligned Benchmark Questions**: {{ comparison.total_aligned_items }}
- **Unscorable responses (counted as incorrect)**:
  - {{ comparison.model_a_name }}: {{ comparison.truncated_a }} truncated (hit max_tokens), {{ comparison.no_answer_a }} no answer found, {{ comparison.api_error_a }} api_error (call failed)
  - {{ comparison.model_b_name }}: {{ comparison.truncated_b }} truncated (hit max_tokens), {{ comparison.no_answer_b }} no answer found, {{ comparison.api_error_b }} api_error (call failed)
- **Accuracy Comparison**:
  - {{ comparison.model_a_name }}: **{{ (comparison.accuracy_a * 100)|round(1) }}%**
  - {{ comparison.model_b_name }}: **{{ (comparison.accuracy_b * 100)|round(1) }}%**
  - **Net Accuracy Delta**: **{{ "%+0.1f"|format(comparison.delta_accuracy * 100) }}%**
- **Statistical Significance (McNemar Test)**:
  - Chi-squared statistic: `{{ comparison.mcnemar.statistic }}`
  - p-value: `{{ comparison.mcnemar.p_value }}`
  - Statistically Significant (alpha = 0.05): **{{ "YES" if comparison.mcnemar.significant else "NO" }}**

---

## 2. Benchmark Breakdown

| Benchmark | Domain | {{ comparison.model_a_name }} | {{ comparison.model_b_name }} | Delta | Reliability |
| :--- | :--- | :---: | :---: | :---: | :--- |
{% for b_id, data in comparison.benchmarks.items() %}
| **{{ data.benchmark_name }}** | {{ data.domain }} | {{ (data.accuracy_a * 100)|round(1) }}% | {{ (data.accuracy_b * 100)|round(1) }}% | {{ "%+0.1f"|format(data.delta * 100) }}% | {% if data.unreliable_a or data.unreliable_b %}{% if data.unreliable_a %}A UNRELIABLE ({{ "%.0f"|format(data.unreliable_fraction_a * 100) }}%) {% endif %}{% if data.unreliable_b %}B UNRELIABLE ({{ "%.0f"|format(data.unreliable_fraction_b * 100) }}%){% endif %}{% else %}ok{% endif %} |
{% endfor %}

---

## 3. Flip Analysis (Item-Level Disagreements)

- **Questions where only {{ comparison.model_b_name }} succeeded**: {{ comparison.b_only_correct_count }}
- **Questions where only {{ comparison.model_a_name }} succeeded**: {{ comparison.a_only_correct_count }}
- **Common Successes**: {{ comparison.both_correct_count }}
- **Common Failures**: {{ comparison.both_failed_count }}

### Sample Flips (Where {{ comparison.model_b_name }} outperformed {{ comparison.model_a_name }}):
{% for flip in comparison.b_wins_flips[:3] %}
#### Question `{{ flip.question_id }}` ({{ flip.benchmark }})
- **Prompt**: {{ flip.prompt }}
- **Ground Truth**: `{{ flip.ground_truth }}`
- **{{ comparison.model_a_name }} Output**: `{{ flip.extracted_a }}` (Incorrect)
- **{{ comparison.model_b_name }} Output**: `{{ flip.extracted_b }}` (Correct)
---
{% endfor %}

---

## 4. Resource & Computational Efficiency
- **Mean Latency Delta**: {{ "%+0.3f"|format(comparison.delta_latency) }} seconds
- **Inference Cost Delta**: {{ "%+0.6f"|format(comparison.delta_cost) }} USD

*Report compliant with UN SDG 9 (Innovation & Infrastructure) and SDG 12 (Responsible Consumption).*
"""

    @classmethod
    def generate_markdown(cls, comparison: Dict[str, Any]) -> str:
        tmpl = Template(cls.MARKDOWN_TEMPLATE)
        return tmpl.render(comparison=comparison)

    @classmethod
    def generate_html(cls, comparison: Dict[str, Any]) -> str:
        md = cls.generate_markdown(comparison)
        html = f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>NeMo Evaluator Benchmark Comparison</title>
    <style>
        body {{ font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; line-height: 1.6; max-width: 900px; margin: 40px auto; padding: 0 20px; color: #24292e; }}
        table {{ border-collapse: collapse; width: 100%; margin: 20px 0; }}
        th, td {{ border: 1px solid #dfe2e5; padding: 10px 14px; text-align: left; }}
        th {{ background-color: #f6f8fa; font-weight: 600; }}
        code {{ background-color: #f0f3f6; padding: 2px 5px; border-radius: 4px; }}
        hr {{ border: 0; height: 1px; background: #e1e4e8; margin: 30px 0; }}
        h1, h2, h3 {{ border-bottom: 1px solid #eaecef; padding-bottom: 0.3em; }}
    </style>
</head>
<body>
<pre style="white-space: pre-wrap; font-family: inherit;">
{md}
</pre>
</body>
</html>
"""
        return html
